    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: #fff;
    color: #0d6efd;
    border: 1px solid #0d6efd;
    padding: 0.625rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.15s;
}

.btn-outline:hover {
    background: #0d6efd;
    color: #fff;
}

.btn-secondary {
    background: #f8f9fa;
    color: #495057;
    border: 1px dashed #adb5bd;
