+        @if (_errors.Count > 0)
+        {
+            <div class="validation-errors">
+                @foreach (var error in _errors)
+                {
+                    <p>@error</p>
+                }
+            </div>
+        }
+
+        <!-- Step 1: Personal Info -->
+        @if (_currentStep == 0)
+        {
+            <div class="step-content">
+                <h2>Personal Information</h2>
+                <div class="form-group">
+                    <label for="fullName">Full Name *</label>
+                    <input id="fullName" type="text" @bind="_fullName" placeholder="Enter your full name" />
+                </div>
+                <div class="form-group">
+                    <label for="email">Email *</label>
+                    <input id="email" type="email" @bind="_email" placeholder="Enter your email" />
+                </div>
+                <div class="form-group">
+                    <label for="phone">Phone *</label>
+                    <input id="phone" type="tel" @bind="_phone" placeholder="Enter your phone number" />
+                </div>
+                <div class="form-group">
+                    <label for="address">Address *</label>
+                    <input id="address" type="text" @bind="_address" placeholder="Enter your address" />
+                </div>
+                <div class="form-actions">
+                    <button class="btn-primary" @onclick="NextStep" disabled="@_isValidating">
+                        @(_isValidating ? "Validating..." : "Next")
+                    </button>
+                </div>
+            </div>
+        }
+
+        <!-- Step 2: Work History -->
+        @if (_currentStep == 1)
+        {
+            <div class="step-content">
+                <h2>Work History</h2>
+                @for (int i = 0; i < _workEntries.Count; i++)
+                {
+                    var index = i;
+                    <div class="work-entry-card">
+                        <div class="work-entry-header">
+                            <h3>Position @(index + 1)</h3>
+                            @if (_workEntries.Count > 1)
+                            {
+                                <button class="btn-danger-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
+                            }
+                        </div>
+                        <div class="form-group">
+                            <label>Company Name *</label>
+                            <input type="text" @bind="_workEntries[index].Company" placeholder="Company name" />
+                        </div>
+                        <div class="form-group">
+                            <label>Job Title *</label>
+                            <input type="text" @bind="_workEntries[index].Title" placeholder="Job title" />
+                        </div>
+                        <div class="form-row">
+                            <div class="form-group">
+                                <label>Start Date *</label>
+                                <input type="date" @bind="_workEntries[index].StartDate" />
+                            </div>
+                            <div class="form-group">
+                                @if (!_workEntries[index].IsCurrent)
+                                {
+                                    <label>End Date</label>
+                                    <input type="date" @bind="_workEntries[index].EndDate" />
+                                }
+                            </div>
+                        </div>
+                        <div class="form-group checkbox-group">
+                            <input type="checkbox" id="current-@index" @bind="_workEntries[index].IsCurrent" />
+                            <label for="current-@index">I currently work here</label>
+                        </div>
+                        <div class="form-group">
+                            <label>Description</label>
+                            <textarea @bind="_workEntries[index].Description" placeholder="Describe your role and responsibilities"></textarea>
+                        </div>
+                    </div>
+                }
+                <button class="btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
+                <div class="form-actions">
+                    <button class="btn-outline" @onclick="PreviousStep">Back</button>
+                    <button class="btn-primary" @onclick="NextStep">Next</button>
+                </div>
+            </div>
+        }
+
+        <!-- Step 3: References -->
+        @if (_currentStep == 2)
+        {
+            <div class="step-content">
+                <h2>References</h2>
+                @for (int i = 0; i < _references.Count; i++)
+                {
+                    var index = i;
+                    <div class="reference-card">
+                        <div class="work-entry-header">
+                            <h3>Reference @(index + 1)</h3>
+                            @if (_references.Count > 2)
+                            {
+                                <button class="btn-danger-sm" @onclick="() => RemoveReference(index)">Remove</button>
+                            }
+                        </div>
+                        <div class="form-group">
+                            <label>Name *</label>
+                            <input type="text" @bind="_references[index].Name" placeholder="Reference name" />
+                        </div>
+                        <div class="form-group">
+                            <label>Relationship *</label>
+                            <input type="text" @bind="_references[index].Relationship" placeholder="e.g. Former Manager" />
+                        </div>
+                        <div class="form-group">
+                            <label>Email *</label>
+                            <input type="email" @bind="_references[index].Email" placeholder="Reference email" />
+                        </div>
+                        <div class="form-group">
+                            <label>Phone</label>
+                            <input type="tel" @bind="_references[index].Phone" placeholder="Reference phone" />
+                        </div>
+                    </div>
+                }
+                @if (_references.Count < 3)
+                {
+                    <button class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
+                }
+                <div class="form-actions">
+                    <button class="btn-outline" @onclick="PreviousStep">Back</button>
+                    <button class="btn-primary" @onclick="NextStep">Next</button>
+                </div>
+            </div>
+        }
+
+        <!-- Step 4: Cover Letter -->
+        @if (_currentStep == 3)
+        {
+            <div class="step-content">
+                <h2>Cover Letter</h2>
+                <div class="form-group">
+                    <label for="coverLetter">Write your cover letter</label>
+                    <textarea id="coverLetter" class="cover-letter-textarea" @bind="_coverLetter" @bind:event="oninput" maxlength="2000" placeholder="Tell us why you're a great fit for this position..."></textarea>
+                    <div class="character-count">@_coverLetter.Length / 2000 characters</div>
+                </div>
+                <div class="form-actions">
+                    <button class="btn-outline" @onclick="PreviousStep">Back</button>
+                    <button class="btn-primary" @onclick="NextStep">Next</button>
+                </div>
+            </div>
+        }
+
+        <!-- Step 5: Review & Submit -->
+        @if (_currentStep == 4)
+        {
+            <div class="step-content">
+                <h2>Review & Submit</h2>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>Personal Information</h3>
+                        <a href="#" @onclick="() => GoToStep(0)" @onclick:preventDefault>Edit</a>
+                    </div>
+                    <dl>
+                        <dt>Full Name</dt><dd>@_fullName</dd>
+                        <dt>Email</dt><dd>@_email</dd>
+                        <dt>Phone</dt><dd>@_phone</dd>
+                        <dt>Address</dt><dd>@_address</dd>
+                    </dl>
+                </div>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>Work History</h3>
+                        <a href="#" @onclick="() => GoToStep(1)" @onclick:preventDefault>Edit</a>
+                    </div>
+                    @foreach (var entry in _workEntries)
+                    {
+                        <div class="review-work-entry">
+                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
+                            <br />
+                            <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
+                            @if (!string.IsNullOrWhiteSpace(entry.Description))
+                            {
+                                <p>@entry.Description</p>
+                            }
+                        </div>
+                    }
+                </div>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>References</h3>
+                        <a href="#" @onclick="() => GoToStep(2)" @onclick:preventDefault>Edit</a>
+                    </div>
+                    @foreach (var reference in _references)
+                    {
+                        <div class="review-reference">
+                            <strong>@reference.Name</strong> (@reference.Relationship)
+                            <br />
+                            <span>@reference.Email @(!string.IsNullOrWhiteSpace(reference.Phone) ? $"| {reference.Phone}" : "")</span>
+                        </div>
+                    }
+                </div>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>Cover Letter</h3>
+                        <a href="#" @onclick="() => GoToStep(3)" @onclick:preventDefault>Edit</a>
+                    </div>
+                    <p class="cover-letter-preview">@_coverLetter</p>
+                </div>
+
+                <div class="form-actions">
+                    <button class="btn-outline" @onclick="PreviousStep">Back</button>
+                    <button class="btn-primary btn-submit" @onclick="SubmitApplication" disabled="@_isSubmitting">
+                        @(_isSubmitting ? "Submitting..." : "Submit Application")
+                    </button>
+                </div>
+            </div>
+        }
+    }
+    else
+    {
+        <!-- Submission Confirmation -->
+        <div class="confirmation">
+            <div class="confirmation-icon">&#10003;</div>
+            <h2>Application Submitted!</h2>
+            <p>Thank you for your application. Your application ID is:</p>
+            <div class="application-id">#@_applicationId</div>
+            <p>We will review your application and get back to you soon.</p>
+        </div>
+    }
+</div>
+
+@code {
+    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+    private int _currentStep = 0;
+    private int _highestCompletedStep = -1;
+    private List<string> _errors = new();
+    private bool _isValidating = false;
+    private bool _isSubmitting = false;
+    private bool _submitted = false;
+    private int _applicationId;
+
+    // Step 1
+    private string _fullName = "";
+    private string _email = "";
+    private string _phone = "";
+    private string _address = "";
+
+    // Step 2
+    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
+
+    // Step 3
+    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4
+    private string _coverLetter = "";
+
+    private string GetStepStatus(int step)
+    {
+        if (step == _currentStep) return "active";
+        if (step <= _highestCompletedStep) return "completed";
+        return "dimmed";
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step <= _highestCompletedStep)
+        {
+            _currentStep = step;
+            _errors.Clear();
+        }
+    }
+
+    private void PreviousStep()
+    {
+        if (_currentStep > 0)
+        {
+            _currentStep--;
+            _errors.Clear();
+        }
+    }
+
+    private async Task NextStep()
+    {
+        _errors.Clear();
+
+        if (!ValidateCurrentStep())
+            return;
+
+        if (_currentStep == 0)
+        {
+            _isValidating = true;
+            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
+            _isValidating = false;
+
+            if (!emailValid)
+            {
+                _errors.Add("Please enter a valid email address.");
+                return;
+            }
+        }
+
+        if (_currentStep > _highestCompletedStep)
+            _highestCompletedStep = _currentStep;
+
+        _currentStep++;
+    }
+
+    private bool ValidateCurrentStep()
+    {
+        switch (_currentStep)
+        {
+            case 0:
+                if (string.IsNullOrWhiteSpace(_fullName)) _errors.Add("Full name is required.");
+                if (string.IsNullOrWhiteSpace(_email)) _errors.Add("Email is required.");
+                if (string.IsNullOrWhiteSpace(_phone)) _errors.Add("Phone is required.");
+                if (string.IsNullOrWhiteSpace(_address)) _errors.Add("Address is required.");
+                break;
+            case 1:
+                for (int i = 0; i < _workEntries.Count; i++)
+                {
+                    var entry = _workEntries[i];
+                    if (string.IsNullOrWhiteSpace(entry.Company)) _errors.Add($"Position {i + 1}: Company name is required.");
+                    if (string.IsNullOrWhiteSpace(entry.Title)) _errors.Add($"Position {i + 1}: Job title is required.");
+                    if (entry.StartDate == default) _errors.Add($"Position {i + 1}: Start date is required.");
+                }
+                break;
+            case 2:
+                for (int i = 0; i < _references.Count; i++)
+                {
+                    var r = _references[i];
+                    if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"Reference {i + 1}: Name is required.");
+                    if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"Reference {i + 1}: Relationship is required.");
+                    if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"Reference {i + 1}: Email is required.");
+                }
+                break;
+            case 3:
+                if (string.IsNullOrWhiteSpace(_coverLetter)) _errors.Add("Cover letter is required.");
+                break;
+        }
+
+        return _errors.Count == 0;
+    }
+
+    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (_workEntries.Count > 1)
+            _workEntries.RemoveAt(index);
+    }
+
+    private void AddReference()
+    {
+        if (_references.Count < 3)
+            _references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (_references.Count > 2)
+            _references.RemoveAt(index);
+    }
+
+    private async Task SubmitApplication()
+    {
+        _isSubmitting = true;
+
+        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
+        var workHistory = new WorkHistory(_workEntries.Select(e =>
+            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
+        var references = _references.Select(r =>
+            new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+
+        var application = new JobApplication(personal, workHistory, references, _coverLetter);
+        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+
+        _isSubmitting = false;
+        _submitted = true;
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = "";
+        public string Title { get; set; } = "";
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = "";
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
+}
+

toolArgs.file_text:
.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step-item.dimmed .step-circle {
    border-color: #dee2e6;
    background: #f8f9fa;
    color: #adb5bd;
}

.step-label {
    font-size: 0.75rem;
    margin-top: 0.25rem;
    text-align: center;
    color: #6c757d;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    margin: 0 0.25rem;
    align-self: center;
    margin-bottom: 1rem;
}

.step-connector.completed {
    background: #198754;
}

/* Form Elements */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #333;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: #495057;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

.form-group textarea {
    min-height: 100px;
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.checkbox-group input[type="checkbox"] {
    width: auto;
}

.checkbox-group label {
    display: inline;
    margin-bottom: 0;
    font-weight: normal;
}

/* Buttons */
.form-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
    border: none;
    padding: 0.625rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: #fff;
    color: #0d6efd;
    border: 1px solid #0d6efd;
    padding: 0.625rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.15s;
}

.btn-outline:hover {
    background: #0d6efd;
    color: #fff;
}

.btn-secondary {
    background: #f8f9fa;
    color: #495057;
    border: 1px dashed #adb5bd;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-bottom: 1rem;
    transition: all 0.15s;
}

.btn-secondary:hover {
    background: #e9ecef;
    border-color: #6c757d;
}

.btn-danger-sm {
    background: #dc3545;
    color: #fff;
    border: none;
    padding: 0.25rem 0.75rem;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
}

.btn-danger-sm:hover {
    background: #bb2d3b;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #495057;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 250px !important;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

/* Validation Errors */
.validation-errors {
    background: #f8d7da;
    border: 1px solid #f5c2c7;
    border-radius: 4px;
    padding: 0.75rem 1rem;
    margin-bottom: 1rem;
}

.validation-errors p {
    margin: 0.25rem 0;
    color: #842029;
    font-size: 0.9rem;
}

/* Review Section */
.review-section {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1.1rem;
}

.review-header a {
    color: #0d6efd;
    text-decoration: none;
    font-size: 0.9rem;
}

.review-header a:hover {
    text-decoration: underline;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #6c757d;
}

.review-section dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    margin: 0;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation-icon {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #198754;
    color: #fff;
    font-size: 2.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.application-id {
    font-size: 1.5rem;
    font-weight: bold;
    color: #0d6efd;
    margin: 1rem 0;
}

